update public.learning_paths
set
  title = 'Child Welfare',
  goal = 'Child Welfare',
  summary = 'Understand why child welfare exists, how it developed, and how its values, laws, and policy tensions shape practice. Use developmental and ecological knowledge to interpret safety, trauma, and protective capacity; map interprofessional systems; and recognize maltreatment without simplistic assumptions about poverty, culture, disability, and family stress. Practice reporting, safety assessment, documentation, family engagement, prevention, placement, and permanency work, and connect courts, evidence-based intervention, equity, tribal sovereignty, transition-age youth supports, and ethical, data-informed reform.',
